import type { Item, LText, Pack } from '../pack';

const L = (enStd: string, enPlain: string, esStd: string, esPlain: string): LText => ({
  en: { std: enStd, plain: enPlain },
  es: { std: esStd, plain: esPlain },
});
const C = (id: string, enStd: string, enPlain: string, esStd: string, esPlain: string) =>
  ({ id, text: L(enStd, enPlain, esStd, esPlain) });

function q(
  id: string, skill: string, prompt: LText, answer: string,
  choices: ReturnType<typeof C>[], explanation?: LText,
): Item {
  return { id, skill, kind: 'choice', prompt, choices, answer, explanation };
}

